// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 blockTimestamp, uint256 prevTimestamp) public {
        // Bound blockTimestamp to be > pastBlockTime (initially 0)
        vm.assume(blockTimestamp > c.pastBlockTime() && blockTimestamp < block.timestamp + 1000000);
        // Bound prevTimestamp to be non-negative (any value)
        // Set the block properties before the call
        vm.warp(blockTimestamp);
        vm.roll(blockNumber);
        // Ensure block.number % 15 != 0 so no transfer happens
        vm.assume(blockNumber % 15 != 0);

        uint256 balanceBefore = address(c).balance;
        // Call fallback with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");
        assertTrue(success);

        uint256 balanceAfter = address(c).balance;
        // The rule: since no transfer occurred, balance should not have decreased (it increased by 10 ether)
        assertTrue(balanceAfter == balanceBefore + 10 ether);
    }
}

